name: custom-ecom-tvc-product-ad
description: 使用此技能将电商产品视频结构化为精致、高端的电视广告（TVC）。在需要高端品牌影片、电影级产品广告或美学产品叙事时触发。不适用于随意、快节奏或用户生成内容（UGC）风格。
