| 敬畏 / 惊奇 | 2C 尺度揭示, 6C 微距到宇宙, 2A 塔可夫斯基漂浮 |
| 活力 / 兴奋 | 3A 斯坦尼康跟随, 6B FPV 无人机, 3C 连续混乱 |
