('Before And After Product Ad','使用此技能来构建视频脚本，展示产品从初始状态到改进结果的转变过程。适用于基于对比的广告格式和以证据为导向的叙事方式。不适用于缺乏可见或直接可观察结果的抽象产品或服务。','---
