| 情感 | 最佳技巧 |
|---------|----------------|
| 酷/自信 | T6 配乐行走，T4 恋物癖特写 |
| 紧张/恐惧 | T10 长镜头对话，T5 墨西哥对峙 |
| 力量/威胁 | T1 后备箱镜头，T7 力量爬行 |
| 冲击/影响 | T8 急推变焦，T2 章节卡 |
| 亲密/揭示 | T3 仪表盘对话，T9 镜像镜头 |
| 复杂性/结构 | T11 时间跳跃，T12 分屏 |
| 黑色幽默 | T1 后备箱镜头，T4 恋物癖特写，T8 急推变焦 |

## AI 模型难度

| 难度 | 技巧 |
|-----------|------------|
| 最容易 | T2 章节卡，T4 恋物癖特写，T8 急推变焦 |
| 中等 | T1 后备箱镜头，T3 仪表盘镜头，T6 配乐行走 |
| 较难 | T9 镜像镜头，T10 长镜头对话，T7 力量爬行 |
| 最难 | T5 墨西哥对峙，T11 时间跳跃，T12 分屏 |

