## 组合序列

### “落水狗开场”
```
片段 1：T3 仪表盘对话——两个角色争论小费问题
片段 2：T2 章节卡——红色背景上的“金发先生”
片段 3：T6 配乐行走——一群穿黑西装的人慢动作行走
片段 4：T5 墨西哥对峙——三把枪指着，摄影机环绕
```

### “杀死比尔复仇入场”
```
片段 1：T4 恋物癖特写——赤脚踩上木地板
片段 2：T8 急推变焦——快速切到目标的脸（认出）
片段 3：T6 配乐行走——新娘向前走，慢动作
片段 4：T10 长镜头对话——面对面，暴力前的沉默
```

### “低俗小说后备箱场景”
```
片段 1：T1 后备箱镜头——两个人向下看，随意交谈
片段 2：T3 仪表盘对话——讨论发生了什么，收音机播放
片段 3：T9 镜像镜头——一个角色在浴室，给自己打气
```

### “时间错乱刺杀”
```
片段 1：T10 长镜头对话——谈判（之后）
片段 2：T2 章节卡——“4 小时前”
片段 3：T6 配乐行走——到达地点（之前）
片段 4：T5 墨西哥对峙——对峙（期间）
片段 5：T1 后备箱镜头——后果（之后之后）
```

### “酷炫介绍”
```
片段 1：T7 力量爬行——地板视角，靴子走进画面
片段 2：T4 恋物癖特写——点燃香烟，烟雾缭绕
片段 3：T6 配乐行走——完全亮相，随着音乐行走
```

---

## 反模式（切勿这样做）

- 切勿将塔伦蒂诺技巧用于健康/可爱内容（错误的工具箱）
- 切勿在没有角色向下看的情况下进行后备箱镜头（这才是重点）
- 切勿仓促进行墨西哥对峙（紧张需要时间）
- 切勿在每个序列中使用超过一次急推变焦（会失去冲击力）
- 切勿选择与时代/角色不匹配的配乐歌曲
- 切勿通过过快剪辑使对话场景变得无聊（保持镜头）
- 切勿忘记塔伦蒂诺的暴力有后果和幽默
- 切勿在没有叙事目的的情况下使用分屏（它不是装饰）
- 切勿让章节卡字体无聊（字体就是个性）
- 切勿在没有视觉区分的情况下使用时间跳跃（观众必须知道）
- 反油腻：塔伦蒂诺的风格大胆但绝不空洞——每种技巧都为角色或紧张服务
- 音乐不是背景——音乐就是场景

---

## 规则

- 每种技巧必须服务于角色或紧张（说明目的）
- 音乐/声音设计对塔伦蒂诺来说是强制性的——除非沉默本身就是紧张，否则永远不要静音
- 调色板：温暖的金色、深红色、刺眼的荧光灯、70 年代模拟感
- 建议使用胶片颗粒以获得符合时代的感觉
- 急推变焦：每个序列最多一次
- 反油腻：酷服务于角色，暴力服务于故事，风格服务于实质
