## 创作规则：组合模块

这个系统的真正力量在于组合。单个镜头由多个模块叠加定义：

**原型 + 情感 + 场景类型 = 完整的叙事镜头**

可选：添加权力动态、关系框架或导演风格叠加以获得更具体的细节。

### 组合公式

```
第1步：镜头中是谁？ ->模块1（原型）建立基础镜头语言
第2步：他们感觉如何？ ->模块4（情感）修改运动和色彩
第3步：发生了什么？ ->模块5（场景类型）提供叙事结构
第4步（可选）：谁有权力？ ->模块2或6（动态/转变）
第5步（可选）：画面中还有谁？ ->模块7（关系）
第6步（可选）：谁的风格？ ->模块8（导演风格叠加）
```

### 组合示例1：反派在对峙中感到恐惧

原型：1.2 反派（荷兰角，冷色调，不对称）
情感：4.3 恐惧（缓慢推进，阴影增长）
场景：5.1 对峙（收紧的正反打）

```
反派体验恐惧的电影化对峙镜头。[反派主体]在[环境]中，轻微荷兰角倾斜7度。镜头从中景缓慢推进至特写。不对称构图，主体被推向画面边缘，6500K冷色主光将面部一分为二，一半在阴影中。随着对峙升级，背景中的阴影逐渐扩大，从画面边缘侵入。焦点偶尔游移，仿佛镜头感知到了反派的不确定性。色温寒冷，且愈发寒冷。通过收紧的镜头暗示正反打，每一次节拍都比上一次更近。反派惯用的视觉语言（荷兰角、阴影、冷光）此刻反噬其身，那些曾令其面目可憎的视觉工具，如今使其陷入困境。推进镜头无情、幽闭。恐惧侵蚀了他们标志性的构图框架。
```

### 示例组合 2：斯皮尔伯格风格的英雄觉醒

原型：1.1 主角（低角度、暖色、居中）
情绪：4.8 决心（稳定推进，在混乱中保持稳定）
场景：5.5 觉醒/转变（角度从高到低变化）
导演：8.1 斯皮尔伯格（面部优先、推进式领悟、背光）

```
斯皮尔伯格风格的英雄觉醒。[英雄主体]在[环境]中。开始：俯视角度，主体渺小、挫败。然后：随着主体决心凝聚，镜头下降至平视高度。面部特写，在领悟瞬间向眼睛稳定推进。随着转变发生，强烈的暖色背光3200K逐渐显现，营造出标志性的斯皮尔伯格光环。40mm镜头，亲密而扎实。主体的表情从挫败转为坚定，眼神因反射光而明亮，下颌紧绷。镜头过渡到10度仰角，现在仰视一位重生的英雄。推进镜头持续而审慎，每一帧都更近，脸庞充满决心。背景温暖，略带柔和，充满可能性。整个转变过程通过斯皮尔伯格式的面部、光线和推进镜头语言捕捉：这个人刚刚领悟了重要的事情。
```

### 示例组合 3：王家卫风格的有毒关系告别

关系：7.7 有毒羁绊（纠缠的轨道，幽闭恐惧）
场景：5.3 告别（缓慢拉远，距离扩大）
情绪：4.5 悲伤（下沉，褪色，远离）
导演：8.3 王家卫（抽帧，霓虹，紧凑，忧郁）

```
王家卫风格的有毒告别。[主体A]和[主体B]在[霓虹灯照亮的城市环境，狭窄走廊，雨水打湿的路面]。镜头进行紧凑的环绕运动，然后开始松开并拉远。抽帧动态模糊创造出两人分离的鬼影轨迹。霓虹色彩晕染：红色和蓝色的倒影在潮湿的路面和皮肤上闪烁。紧凑幽闭的构图缓慢而痛苦地扩大，一人转身离去。纠缠的构图在字面上解开。镜头带着4.5级的悲伤向后拉，略微下沉，画面色调变冷。混合霓虹色温：2800K的钨丝暖光逐渐消亡，6500K的冷蓝光向前推进。浅景深使离去的身影变得柔和，而留下的人则带着痛苦的清晰度变得锐利。通过抽帧，时间变得富有弹性：有些时刻被拉长，有些被压缩。这场告别既漫长又瞬间结束。美丽、心痛、浸染霓虹的失落。
```

### 示例组合 4：启示时刻的师徒权力转移

关系：7.6 师徒（身高差趋于平等）
权力转移：6.2 启示（焦点转换，光线变化）
场景：5.5 觉醒（角度变化）
情绪：4.6 学生的胜利（上升，金色迸发）

```
师徒启示与权力平衡。[学生主体]和[师父主体]在[环境]中。开始：师父在画面中位置更高，采用仰角凸显师父的权威，学生位于下方。师父身上是温暖自信的光线，学生身上是平淡中性的光线。启示时刻：焦点从师父转移到场景中的物体/证据/真相，然后转移到学生的脸上。光线开始变化：新的光源温暖了学生的脸庞，师父自信的光线变得柔和。随着镜头角度逐渐放平，学生在画面中上升。50mm镜头。师父的主导地位随着学生理解的加深而逐渐削弱。色温趋于平衡：师父的温暖自信扩散到学生身上。画面中的身高差逐渐减小。镜头最终稳定在两者之间真正的平视高度。最后一帧：两者高度相同，光线相同，画面空间相同。学生获得了启示，使其与师父平起平坐。视觉等级因理解的力量而消解。
```

### 示例组合 5：维伦纽瓦风格的反派孤独死亡场景

原型：1.2 反派（冷色，不对称）
情绪：4.1 孤独（广角，空旷，冷色）
场景：5.10 死亡场景（下沉，淡出，远离）
导演：8.6 维伦纽瓦（广阔负空间，环境恐惧）

```
维伦纽瓦风格的反派孤独死亡。[反派主体]在[广阔荒凉的环境]中。极广角镜头，反派在画面中显得渺小，24mm镜头。定义其反派身份的不对称荷兰角随着力量流失而缓慢放平。广阔的负空间压倒一切：天空、荒地、空旷填满画面。镜头进行难以察觉的拉远，本已渺小的身影进一步缩小。冷色温6000K，去饱和，没有温暖的慰藉。无限远深焦，冷漠的风景清晰而永恒，反派则逐渐消逝。光线平淡、漫射，曾为其威胁服务的刺骨冷光，如今只剩下寒冷。对主体的焦点开始变软，并非戏剧性地，而是带着5.10级死亡场景的平静顺从。环境并未哀悼。在这身影消失后，这片风景仍将长久存在。寂静作为视觉存在。反派的死亡并非通过戏剧性的特写，而是作为一个被冷漠的广阔空间吞噬的小小形状。负空间获胜。
```

### 决策矩阵：快速参考

| 我需要展示... | 主要模块 | 支持模块 | 结果 |
|---|---|---|---|
| 英雄是谁 | M1.1 主角 | M3.1 英雄登场 | 观众识别并支持这个角色 |
| 谁拥有权力 | M2 权力动态 | M1 匹配原型 | 无需对话即可展现权力关系 |
| 权力易手 | M6 权力转移 | M4 情绪状态 | 逆转时刻被切身感受 |
| 两人渐行渐远 | M7.3 距离扩大 | M4.5 悲伤 | 通过扩大的画面展现关系死亡 |
| 两人重归于好 | M7.5 和解 | M5.9 重逢 | 通过汇聚的视觉语言展现疗愈 |
| 角色崩溃 | M4.10 疯狂 | M6.3 临界点 | 通过镜头崩溃展现心理崩溃 |
| 史诗高潮 | M5.6 最终决战 | M4.8 决心 | 规模 + 聚焦的英雄时刻 |
| 悬念营造 | M5.7 秘密会面 | M8.5 希区柯克叠加 | 偷窥的紧张感，观众知道得更多 |
| 视觉诗意 | M4.4 爱 | M8.3 王家卫叠加 | 忧郁之美，时间凝固 |
| 冷峻精确 | 任何场景类型 | M8.2 库布里克叠加 | 数学化、几何化、可控的恐惧 |

