## 模块 13：三步镜头公式——先问“为什么”，再问“是什么”，最后问“怎么做”

导演的决策过程必须遵循三个强制步骤。永远不要从镜头运动开始。始终从理由开始。

这个公式可以防止AI视频生成中最常见的错误：选择看起来很酷但对叙事毫无意义的镜头语言。

### 第一步：为什么——这场戏的叙事目的是什么？

在进行任何技术决策之前，先回答这些问题：

```
“为什么”检查清单

1. 观众观看这个镜头时应该感受到什么情绪？
   [恐惧 / 爱 / 敬畏 / 恐惧 / 兴奋 / 悲伤 / 紧张 / 释放 / 惊奇 / 不适]

2. 镜头代表谁的视角？
   [主角的体验 / 反派的控制 / 中立的观察者 / 隐藏的窥视者 / 上帝视角 / 受害者的无助]

3. 正在管理什么信息？
   [揭示新事物 / 对观众隐藏某些信息 / 对角色隐藏但向观众展示 / 确认之前的怀疑]

4. 这个画面中的权力状态是什么？
   [一方主导 / 平等 / 权力转移 / 权力模糊 / 权力缺失]

5. 这处于场景弧线的哪个位置？
   [开场平静 / 紧张升级 / 高潮 / 余波 / 过渡]

你对这5个问题的回答决定了关于镜头的所有事情。如果你无法回答它们，你就还没准备好选择镜头运动。
```

### 第二步：是什么——从模块中选择镜头语言

将你的“为什么”答案映射到特定的模块选择：

```
“是什么”映射

你的情绪答案 -> 模块 4 (情绪状态)
  示例：“观众应该感到恐惧” -> M4.3 恐惧/恐惧 -> 缓慢推进，阴影，不稳定

你的视角答案 -> 模块 1 (原型) 或 模块 11 (戏剧性讽刺)
  示例：“隐藏的窥视者视角” -> M11.2 隐藏的观察者 -> 长焦，遮挡视野

你的信息答案 -> 模块 9 (剧本划线) 节拍映射
  示例：“揭示新事物” -> 揭示弧线 -> 焦点转换，拉宽，深焦

你的权力答案 -> 模块 2 (权力动态) 或 模块 6 (权力转移)
  示例：“权力转移” -> M6.1 局势逆转 -> 角度反转

你的弧线位置答案 -> 模块 9.4 (场景弧线模板)
  示例：“紧张升级” -> 升级弧线 节拍3 -> 收紧，冷却，不稳定

将选定的模块组合成一个连贯的镜头指令。
```

### 第三步：怎么做——AI视频提示词的技术执行

将你的“是什么”选择转换为具体的技术参数：

```
“怎么做”模板

基于“为什么”和“是什么”分析，完整的技术提示词：

相机位置：[角度（度），相对于主体的高度]
镜头：[焦距]mm
运动：[类型] 以 [速度描述：不易察觉/慢/中/快/突然]
构图：[构图规则，头顶空间，主体位置]
焦点：[景深，焦点转换目标，焦点行为]
主光：[色温]K，[硬/柔]，[方向]，[质量]
补光：[比例，颜色，方向]
色彩调色板：[主色调，饱和度水平，色温弧线]
主体方向：[动作，表情，姿势，相对于相机的运动]
环境角色：[背景功能：支持/威胁/矮化/拥抱/困住]
负面提示词：[要排除的相关伪影]

组装后的提示词：
[将以上所有内容组合成自然语言的完整、可复制粘贴的提示词]
```

### 三步公式实践——完整示例

**场景：** 一名侦探意识到他们的搭档一直是凶手。办公室环境，夜晚。

```
第一步：为什么
  情绪：背叛的震惊，然后是恐惧
  视角：侦探的主观体验
  信息：戏剧性讽刺的回报（观众可能已经怀疑；侦探现在发现）
  权力：转移——搭档隐藏了权力，现在被揭示
  弧线位置：揭示弧线的高潮

第二步：是什么
  M4.9 背叛/震惊 -> 推拉变焦，色彩从暖色跳变到冷色
  M1.1 主角镜头 -> 通常是低角度暖色，但现在被打乱
  M11.5 戏剧性讽刺回报 -> 发现的面孔，累积的紧张感释放
  M6.2 揭示 -> 焦点转换，光线变化
  M9.4 揭示弧线 节拍4 -> 全部真相，深焦，展示一切

第三步：怎么做
  相机：平视，开始推拉变焦
  镜头：50mm 变焦到 85mm 同时向后拉
  运动：推拉变焦（眩晕效果），缓慢，令人作呕
  构图：以侦探的脸为中心，搭档在背景中可见
  焦点：侦探清晰，变焦时焦点转换到搭档，再回到侦探
  主光：从温暖的 3800K 台灯跳变到寒冷的 6000K 顶置荧光灯
  补光：逐渐消失，阴影增大
  色彩：温暖的琥珀色褪去，变成冰冷的蓝灰色
  主体：侦探的表情凝固，理解时的微表情
  环境：办公室从安全的工作空间转变为陷阱

  组装后的提示词：
  电影感推拉变焦，平视镜头。侦探[主体]坐在[黑暗办公室，夜晚]的办公桌前，镜头同时向后拉和向前变焦，营造希区柯克眩晕效果。主体的脸保持相同大小，而办公室背景令人作呕地扭曲和拉伸。色温从温暖的 3800K 台灯光芒跳变到寒冷的 6000K 顶置荧光灯。焦点从侦探的脸转换到站在身后门口的搭档的剪影，然后迅速切回。侦探的表情在意识到的那一刻凝固：理解的精确微秒。温暖的琥珀色光线在画面中消逝，被冰冷的蓝灰色取代。阴影在墙壁上蔓延。背景扭曲使熟悉的办公室突然变得陌生和具有威胁性。镜头保持眩晕效果一段令人不适的长节拍。安全的世界已经结束。真相是冰冷的。
```

