在最终确定基于此系统构建的任何提示词之前，请验证：

- [ ] **角色原型镜头语言** 已建立 (模块 1)
- [ ] **镜头焦距** 已指定 (24mm/35mm/50mm/85mm/135mm)
- [ ] **相机角度** 已定义 (低角度/平视/高角度，指定度数)
- [ ] **相机运动** 类型和速度已明确 (静态/推进/拉远/环绕/升降/跟拍)
- [ ] **灯光色温** 已以开尔文指定 (2800K-6500K 范围)
- [ ] **灯光方向和质量** 已描述 (主光角度，硬/柔，有/无补光)
- [ ] **景深** 已处理 (浅/深/中，什么在焦点内)
- [ ] **构图** 已指定 (居中/三分法/不对称，头顶空间)
- [ ] **色彩调色板** 方向已给出 (暖/冷/去饱和/特定色调)
- [ ] **主体动作或表情** 已描述
- [ ] **环境对叙事的贡献** 已包含
- [ ] **负面提示词** 已根据镜头类型附加
- [ ] **提示词中不出现任何中文文本**
- [ ] **占位符** [主体]、[环境]、[动作] 已存在以供自定义

